'use strict';
class PlaceDiscovery {
 constructor(places,navigation,cellAt,getState,inspect,setRegion){this.places=places;this.navigation=navigation;this.getState=getState;this.inspect=inspect;this.setRegion=setRegion;this.rankCache=new Map();this.rows=[];this.results=[];this.active=-1;this.input=document.getElementById('place-search');this.list=document.getElementById('place-results');this.normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();this.europe=new Set(['Albania','Andorra','Austria','Belarus','Belgium','Bosnia and Herzegovina','Bulgaria','Croatia','Cyprus','Czechia','Czech Republic','Denmark','Estonia','Faroe Islands','Finland','France','Germany','Gibraltar','Greece','Guernsey','Hungary','Iceland','Ireland','Isle of Man','Italy','Jersey','Kosovo','Latvia','Liechtenstein','Lithuania','Luxembourg','Malta','Moldova','Monaco','Montenegro','Netherlands','North Macedonia','Norway','Poland','Portugal','Romania','Russia','San Marino','Serbia','Slovakia','Slovenia','Spain','Sweden','Switzerland','Turkey','Ukraine','United Kingdom','Vatican']);
 this.entries=[];const groups=new Map();for(const p of places){const region=this.regionFor(p),cell=cellAt(p[2],p[3]);const entry={type:'city',name:p[1],subtitle:[p[4],p[5]].filter(Boolean).join(', '),place:p,region,index:cell.index,distance:cell.best,population:p[6]||0};entry.normalizedName=this.normalize(entry.name);entry.text=this.normalize(entry.name+' '+entry.subtitle+(p[1]==='New York City'?' nyc':''));this.entries.push(entry);if(p[4]){const key=p[4]+'|'+p[5];if(!groups.has(key)||entry.population>groups.get(key).population)groups.set(key,entry);}}
 for(const [key,city] of groups){const name=city.place[4],country=city.place[5],feature=country==='United States'?navigation.states.features.find(f=>f.properties.name===name||(name==='Washington, D.C.'&&f.properties.abbr==='DC')):null;const e={type:feature?'state':'region',name:feature?feature.properties.name:name,subtitle:country,place:city.place,region:city.region,population:city.population,feature};e.normalizedName=this.normalize(e.name);e.alias=this.normalize(feature?.properties.abbr||'');e.text=this.normalize(e.name+' '+country+' '+e.alias);this.entries.push(e);}
 this.input.addEventListener('input',()=>{clearTimeout(this.timer);this.timer=setTimeout(()=>this.renderSearch(),100);});this.input.addEventListener('focus',()=>{if(this.input.value.trim().length>=2)this.renderSearch();});this.input.addEventListener('keydown',e=>{if(e.key==='Escape'){this.close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){if(!this.results.length)return;e.preventDefault();this.active=(this.active+(e.key==='ArrowDown'?1:-1)+this.results.length)%this.results.length;this.highlight();}else if(e.key==='Enter'){e.preventDefault();if(this.results.length)this.select(this.results[this.active>=0?this.active:0]);}});document.addEventListener('click',e=>{if(!e.target.closest('.location-search'))this.close();});document.getElementById('rank-population').onchange=()=>this.renderRanking();document.getElementById('rank-spread').onchange=()=>this.renderRanking();
 }
 regionFor(p){if(p[5]==='United States')return 'usa';if(this.europe.has(p[5])&&p[2]>=34&&p[2]<=72&&p[3]>=-25&&p[3]<=45)return 'europe';return 'world';}
 search(query){const q=this.normalize(query);if(q.length<2)return [];const tokens=q.split(/\s+/),region=this.getState().currentRegion;return this.entries.filter(e=>tokens.every(t=>e.text.includes(t))).map(e=>({e,weight:(e.normalizedName===q||e.alias===q?100:e.normalizedName.startsWith(q)?50:0)+(e.region===region?10:0)+(e.type==='city'?2:0)})).sort((a,b)=>b.weight-a.weight||b.e.population-a.e.population||a.e.name.localeCompare(b.e.name)).slice(0,8).map(v=>v.e);}
 close(){this.list.hidden=true;this.input.setAttribute('aria-expanded','false');this.input.removeAttribute('aria-activedescendant');this.active=-1;}
 highlight(){[...this.list.children].forEach((li,i)=>li.setAttribute('aria-selected',String(i===this.active)));if(this.active>=0){this.input.setAttribute('aria-activedescendant','place-result-'+this.active);this.list.children[this.active].scrollIntoView({block:'nearest'});}}
 renderSearch(){this.results=this.search(this.input.value);this.active=-1;this.list.replaceChildren();if(this.input.value.trim().length<2){this.close();return;}for(const [i,e] of this.results.entries()){const li=document.createElement('li');li.id='place-result-'+i;li.setAttribute('role','option');li.setAttribute('aria-selected','false');li.append(document.createTextNode(e.name));const small=document.createElement('small');small.textContent=(e.type==='city'?'City':e.type==='state'?'US state':'Region')+' · '+e.subtitle;li.append(small);li.onclick=()=>this.select(e);this.list.append(li);}this.list.hidden=!this.results.length;this.input.setAttribute('aria-expanded',String(this.results.length>0));document.getElementById('search-message').textContent=this.results.length?'Choose a result, or use arrow keys and Enter.':this.getState().busy?'Map is loading. You can search now and choose a place when it is ready.':'No matching place in the catalog. Try the city name plus state or country.';}
 select(e){if(this.getState().busy){document.getElementById('search-message').textContent='Wait for the map calculation to finish, then select this place.';return;}const p=e.place,s=this.getState();if(e.type==='state'||s.currentRegion!=='world'&&e.region!==s.currentRegion)this.setRegion(e.region);if(e.region==='usa'&&this.getState().currentRegion==='usa'){this.navigation.usaView=p[4]==='Alaska'?'alaska':p[4]==='Hawaii'?'hawaii':'contiguous';}if(e.feature){this.navigation.fitFeature(e.feature);}else this.navigation.focus(p[2],p[3],7);this.inspect(p[2],p[3]);const note=document.getElementById('selection-note');if(e.type!=='city'){note.hidden=false;note.textContent=`${e.name} view · showing ${p[1]}'s climate cell, not a region-wide average.`;}this.input.value=e.name;this.close();document.getElementById('search-message').textContent=e.type==='city'?`${e.name}, ${e.subtitle} selected.`:`${e.name} selected. Results below are for ${p[1]}.`;document.getElementById('map').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 loading(){this.rows=[];document.getElementById('city-ranking').replaceChildren();document.getElementById('ranking-status').textContent='Updating city results…';}
 rank(){const s=this.getState();if(s.busy)return [];const minimum=Number(document.getElementById('rank-population').value),spread=document.getElementById('rank-spread').checked;if(this.rankScore!==s.scoreValues||this.rankDays!==s.dayValues){this.rankCache.clear();this.rankScore=s.scoreValues;this.rankDays=s.dayValues;}const cacheKey=[s.currentRegion,s.view,minimum,spread,s.cityFilters?.signature].join('|'),cached=this.rankCache.get(cacheKey);if(cached){this.eligibleCount=cached.count;return cached.rows;}const eligible=this.entries.filter(e=>e.type==='city'&&(!s.cityFilters||s.cityFilters.allows(e))&&e.population>=minimum&&(s.currentRegion==='world'||e.region===s.currentRegion)&&e.distance<=.75&&Number.isFinite(s.scoreValues[e.index])&&Number.isFinite(s.dayValues[e.index])).map(e=>({...e,score:s.scoreValues[e.index],days:s.dayValues[e.index],count:s.coverage[e.index]}));const metric=s.view==='days'?'days':'score',secondary=s.view==='days'?'score':'days';eligible.sort((a,b)=>b[metric]-a[metric]||b[secondary]-a[secondary]||b.population-a.population||a.name.localeCompare(b.name)||a.place[0]-b.place[0]);this.eligibleCount=eligible.length;const seen=new Set(),rows=[];for(const e of eligible){if(spread&&seen.has(e.index))continue;seen.add(e.index);rows.push(e);if(rows.length===10)break;}this.rankCache.set(cacheKey,{rows,count:this.eligibleCount});return rows;}
 renderRanking(){const s=this.getState();if(s.busy){this.loading();return;}const label={world:'World',europe:'Europe regional area',usa:'USA · all states'}[s.currentRegion],metric=s.view==='days'?'comfortable days per year':'average comfort score';document.getElementById('ranking-description').textContent=`${label} · ${s.period==='mean'?'2020–2025 average':s.period} · highest ${metric}. Follows the region tab, not your zoom.`;this.rows=this.rank();const ol=document.getElementById('city-ranking');ol.replaceChildren();const n=v=>Number(v).toLocaleString('en',{maximumFractionDigits:1});for(const e of this.rows){const li=document.createElement('li'),button=document.createElement('button'),place=document.createElement('span'),metrics=document.createElement('span');place.className='rank-place';const name=document.createElement('strong'),sub=document.createElement('small');name.textContent=e.name;sub.textContent=e.subtitle;place.append(name,sub);metrics.className='rank-metrics';const value=document.createElement('strong'),other=document.createElement('small');value.textContent=s.view==='days'?`${n(e.days)} days/yr`:`${n(e.score)} / 10`;other.textContent=s.view==='days'?`${n(e.score)} / 10`:`${n(e.days)} days/yr`;metrics.append(value,other);button.append(place,metrics);button.onclick=()=>this.select(e);li.append(button);ol.append(li);}document.getElementById('ranking-status').textContent=this.rows.length?`${this.eligibleCount.toLocaleString('en')} eligible catalog cities · click a city to inspect`:'No catalog cities meet these filters, size and data-coverage requirements. Try relaxing a filter or changing its year.';}
}

window.PlaceDiscovery=PlaceDiscovery;
